/**
 * Type-level plumbing for `createClient<Database>(url, key)`.
 *
 * `Database` is the type generated by `motherbase gen types typescript`, which
 * emits the exact shape supabase-js emits. Everything here reads that shape and
 * nothing else, so a `database.types.ts` produced by Supabase's own generator
 * works unchanged.
 *
 * This file is types only: it contains no runtime code. The query builder it
 * describes is the existing `PostgrestQueryBuilder`; `MotherbaseClient.from()`
 * hands back the same object viewed through this narrower interface.
 */
import type {
  ExplainOptions,
  InsertOptions,
  MutateOptions,
  OrderOptions,
  PaginateOptions,
  PostgrestArrayOperand,
  PostgrestExplainBuilder,
  PostgrestFilterOperator,
  PostgrestIsValue,
  PostgrestResponse,
  PostgrestTextBuilder,
  ReferencedTableOption,
  RpcOptions,
  SelectOptions,
  TextSearchType,
  UpsertOptions,
} from '../postgrest/index.js';

// ── The generated `Database` shape ────────────────────────────────────────────

export interface GenericTable {
  Row: Record<string, unknown>;
  Insert: Record<string, unknown>;
  Update: Record<string, unknown>;
  Relationships?: unknown;
}

export interface GenericView {
  Row: Record<string, unknown>;
  Relationships?: unknown;
}

export interface GenericFunction {
  Args: Record<string, unknown>;
  Returns: unknown;
}

export interface GenericSchema {
  Tables: Record<string, GenericTable>;
  Views: Record<string, GenericView>;
  Functions: Record<string, GenericFunction>;
  Enums?: Record<string, unknown>;
  CompositeTypes?: Record<string, unknown>;
}

/**
 * The default when no `Database` is supplied. Every relation name is accepted
 * and every row is `Record<string, unknown>`, which is exactly how the SDK
 * behaved before generics existed. Passing a generated `Database` is opt-in.
 */
export type GenericDatabase = Record<string, GenericSchema>;

/**
 * The schema a client reads by default. `public` when the database has one,
 * otherwise whatever single schema was generated: `motherbase gen types
 * typescript --schema shop` emits only `shop`, and requiring every call site to
 * pass the name again would be pure friction.
 */
export type DefaultSchemaName<Database> = 'public' extends keyof Database ? 'public' : SchemaNames<Database>;

/**
 * `motherbase gen types` puts what the SDK addresses by name outside Postgres
 * (edge functions, buckets) under this key, the way supabase-js reserves
 * `__InternalSupabase`. It is not a schema.
 */
type ResourcesKey = '__InternalMotherbase';

/** Every key of a generated `Database` that is a schema. */
export type SchemaNames<Database> = Exclude<keyof Database, ResourcesKey>;

type Resource<Database, Kind extends string> = Database extends { [K in ResourcesKey]: { [P in Kind]: infer N extends string } }
  ? N
  : never;

/**
 * A known name autocompletes, and any other string still compiles: functions
 * and buckets are created from the Studio at runtime, so the generated file is
 * routinely older than the project, and refusing a new name until someone
 * regenerates would make the types a step in every deploy.
 */
type KnownOr<Name extends string> = Name | (string & {});

/** Edge function routes from the generated `Database`, for `functions.invoke`. */
export type EdgeFunctionName<Database> = KnownOr<Resource<Database, 'EdgeFunctions'>>;

/** Bucket slugs from the generated `Database`, for `storage.from`. */
export type BucketName<Database> = KnownOr<Resource<Database, 'Buckets'>>;

export type SchemaOf<Database, Name> = Name extends keyof Database
  ? Database[Name] extends GenericSchema
  ? Database[Name]
  : GenericSchema
  : GenericSchema;

/** Tables and views together: both are selectable through `.from()`. */
export type Relations<Schema extends GenericSchema> = Schema['Tables'] & Schema['Views'];

export type RelationName<Schema extends GenericSchema> = string & keyof Relations<Schema>;

export type RowOf<Schema extends GenericSchema, Name extends RelationName<Schema>> =
  Relations<Schema>[Name] extends { Row: infer R } ? R : never;

// A view has no Insert/Update. Writing to one is rejected at the type level by
// falling back to `never`, which makes `.insert()` uncallable rather than
// silently accepting a payload the server will refuse.
export type InsertOf<Schema extends GenericSchema, Name extends RelationName<Schema>> =
  Name extends keyof Schema['Tables']
  ? Schema['Tables'][Name] extends { Insert: infer I }
  ? I
  : never
  : never;

export type UpdateOf<Schema extends GenericSchema, Name extends RelationName<Schema>> =
  Name extends keyof Schema['Tables']
  ? Schema['Tables'][Name] extends { Update: infer U }
  ? U
  : never
  : never;

export type FunctionName<Schema extends GenericSchema> = string & keyof Schema['Functions'];

export type FunctionArgs<Schema extends GenericSchema, Name extends FunctionName<Schema>> =
  Schema['Functions'][Name] extends { Args: infer A } ? A : never;

export type FunctionReturns<Schema extends GenericSchema, Name extends FunctionName<Schema>> =
  Schema['Functions'][Name] extends { Returns: infer R } ? R : never;

// ── Parsing a PostgREST `select` string ───────────────────────────────────────

type Trim<S extends string> = S extends ` ${infer Rest}`
  ? Trim<Rest>
  : S extends `${infer Rest} `
  ? Trim<Rest>
  : S;

/** `'id, name'` -> `'id' | 'name'`. */
type SplitColumns<S extends string> = S extends `${infer Head},${infer Tail}`
  ? Trim<Head> | SplitColumns<Tail>
  : Trim<S>;

/** `'created_at::text'` -> `'created_at'`. Casts change the wire type, not the source column. */
type StripCast<S extends string> = S extends `${infer Column}::${string}` ? Column : S;

// Alias splitting runs on the cast-stripped name, and it must be its own alias
// so the type parameter stays "naked" and keeps distributing over the union
// `SplitColumns` produced. `StripCast<S> extends ...` inside one conditional
// would test the whole union at once and match nothing.
type AliasPart<S extends string> = S extends `${infer Alias}:${string}` ? Alias : S;
type ColumnPart<S extends string> = S extends `${string}:${infer Column}` ? Column : S;

/** `'writer:author_id'` -> `'writer'` (the key the row will carry). */
type OutputName<S extends string> = AliasPart<StripCast<S>>;

/** `'writer:author_id'` -> `'author_id'` (the column the type comes from). */
type SourceName<S extends string> = ColumnPart<StripCast<S>>;

/**
 * SEAM: relational embedding (`select=*,author(*)`) is not implemented on the
 * server yet, so a select string containing a parenthesised relation is not
 * narrowed. It resolves to the base row plus an open index signature, which
 * types the columns we do know and leaves the embedded keys accessible without
 * pretending we know their shape.
 *
 * When embedding lands, replace this with a resolver that walks
 * `Relationships` to decide object vs array and recurse into the target row.
 */
export type EmbeddedSelectSeam<Row> = Row & Record<string, unknown>;

type IsEmbeddedSelect<S extends string> = S extends `${string}(${string}` ? true : false;

/** Columns named in the select string that the relation does not have. */
export type UnknownSelectColumns<Row, S extends string> = Exclude<
  SourceName<SplitColumns<S>>,
  (keyof Row & string) | '*'
>;

/**
 * The `columns` argument type. Resolves to `unknown` (no extra constraint) when
 * every named column exists, and to an error-message string literal otherwise,
 * so a typo fails at the call site with the offending name in the message.
 */
export type ValidateSelect<Row, S extends string> = IsEmbeddedSelect<S> extends true
  ? unknown
  : [UnknownSelectColumns<Row, S>] extends [never]
  ? unknown
  : `Unknown column in select: ${UnknownSelectColumns<Row, S> & string}`;

/** The row shape a select resolves to. */
export type SelectResult<Row, S extends string> = IsEmbeddedSelect<S> extends true
  ? EmbeddedSelectSeam<Row>
  : '*' extends SplitColumns<S>
  ? Row
  : { [K in SplitColumns<S> as OutputName<K>]: Row[SourceName<K> & keyof Row] };

// ── The typed query builder ───────────────────────────────────────────────────

export type FilterValue = string | number | boolean | null;

/** A write without `.select()` stays `null` through re-typing and `.single()`. */
type RowsUnlessWrite<Data, Rows> = Data extends null ? null : Rows;

/** Columns that can be filtered or ordered on. Any string when untyped. */
export type ColumnName<Row> = keyof Row & string;

/**
 * The `.from()` result. Structurally the existing `PostgrestQueryBuilder`, with
 * the generated row/insert/update types threaded through. `Result` tracks what
 * the current `select` narrowed the row to; it starts as the full row.
 *
 * `Data` is what awaiting resolves to. A write is sent with `return=minimal`
 * and resolves `data: null` until `.select()` asks for the rows back, as in
 * supabase-js; typing it as rows let `data.id` after a bare `insert()` compile
 * and fail at runtime.
 */
export interface TypedQuery<Row, Insert, Update, Result = Row, Data = Result[]>
  extends PromiseLike<PostgrestResponse<Data>> {
  /**
   * Choose the columns to read, as a PostgREST select string. The result type
   * narrows to those columns. After a write (`insert`, `update`, ...), asks for
   * the written rows back: without it a write resolves `data: null`.
   *
   * @param columns Comma-separated columns, `*` for all. Supports aliases
   *   (`label:name`) and embedded relations (`author(name)`).
   * @param options `count: 'exact' | 'planned' | 'estimated'` puts a total in
   *   `count`; `head: true` returns only that count, without rows.
   * @example client.from('posts').select('id, title, author(name)')
   */
  select<S extends string = '*'>(
    columns?: S & ValidateSelect<Row, S>,
    options?: SelectOptions,
  ): TypedQuery<Row, Insert, Update, SelectResult<Row, S>>;

  /**
   * Insert one row or several. Resolves `data: null` unless followed by
   * `.select()`.
   * @example client.from('posts').insert({ title }).select().single()
   */
  insert(
    values: Insert | readonly Insert[],
    options?: InsertOptions,
  ): TypedQuery<Row, Insert, Update, Result, null>;
  /**
   * Insert, or update the row that already has the same primary key (or the
   * same values in the `onConflict` columns). `ignoreDuplicates: true` skips
   * that row instead of updating it.
   */
  upsert(
    values: Insert | readonly Insert[],
    options?: UpsertOptions,
  ): TypedQuery<Row, Insert, Update, Result, null>;
  /**
   * Update the rows matched by the filters that follow. A filter is required:
   * the server refuses an update of the whole table.
   * @example client.from('posts').update({ title }).eq('id', id)
   */
  update(values: Update, options?: MutateOptions): TypedQuery<Row, Insert, Update, Result, null>;
  /**
   * Delete the rows matched by the filters that follow. A filter is required:
   * the server refuses a delete of the whole table.
   * @example client.from('posts').delete().eq('id', id)
   */
  delete(options?: MutateOptions): TypedQuery<Row, Insert, Update, Result, null>;

  /** Rows where `column` equals `value`. Test NULL with `is(column, null)`. */
  eq(column: ColumnName<Row>, value: FilterValue): this;
  /** Rows where `column` differs from `value`. */
  neq(column: ColumnName<Row>, value: FilterValue): this;
  /** Rows where `column` is greater than `value`. */
  gt(column: ColumnName<Row>, value: FilterValue): this;
  /** Rows where `column` is greater than or equal to `value`. */
  gte(column: ColumnName<Row>, value: FilterValue): this;
  /** Rows where `column` is less than `value`. */
  lt(column: ColumnName<Row>, value: FilterValue): this;
  /** Rows where `column` is less than or equal to `value`. */
  lte(column: ColumnName<Row>, value: FilterValue): this;
  /** Case-sensitive pattern match. `%` (or `*`) matches any run of characters. */
  like(column: ColumnName<Row>, pattern: string): this;
  /** Case-insensitive pattern match. `%` (or `*`) matches any run of characters. */
  ilike(column: ColumnName<Row>, pattern: string): this;
  /** Rows where `column` matches every pattern (case-sensitive). */
  likeAllOf(column: ColumnName<Row>, patterns: readonly string[]): this;
  /** Rows where `column` matches at least one pattern (case-sensitive). */
  likeAnyOf(column: ColumnName<Row>, patterns: readonly string[]): this;
  /** Rows where `column` matches every pattern (case-insensitive). */
  ilikeAllOf(column: ColumnName<Row>, patterns: readonly string[]): this;
  /** Rows where `column` matches at least one pattern (case-insensitive). */
  ilikeAnyOf(column: ColumnName<Row>, patterns: readonly string[]): this;
  /** Rows where `column` is one of `values`. */
  in(column: ColumnName<Row>, values: readonly FilterValue[]): this;
  /** Rows where `column` IS `null`, `true`, `false` or `unknown`: the way to test NULL. */
  is(column: ColumnName<Row>, value: PostgrestIsValue): this;

  /** One `eq()` per key, ANDed: `match({ status: 'live', owner_id: id })`. */
  match(query: Partial<Record<ColumnName<Row>, FilterValue>>): this;
  /**
   * Negate a filter: `not('status', 'eq', 'draft')`. The column is a free
   * string, so json paths (`data->>k`) work.
   */
  not(
    column: string,
    operator: PostgrestFilterOperator | (string & {}),
    value: FilterValue | readonly FilterValue[],
  ): this;
  /**
   * Any PostgREST operator by name, for those without a dedicated method:
   * `filter('price', 'isdistinct', null)`. The column is a free string, so json
   * paths (`data->>k`) work.
   */
  filter(
    column: string,
    operator: PostgrestFilterOperator | (string & {}),
    value: FilterValue | readonly FilterValue[],
  ): this;
  /**
   * Rows matching at least one condition, in PostgREST syntax. Nests with
   * `and(...)`: `or('status.eq.live,and(price.gt.10,stock.gt.0)')`.
   */
  or(filters: string, options?: ReferencedTableOption): this;

  /**
   * Full-text search on a `tsvector` (or text) column.
   * @param options `type`: `'plain'`, `'phrase'` or `'websearch'` (search-engine
   *   syntax); `config`: the text search language, e.g. `'english'`.
   */
  textSearch(
    column: ColumnName<Row>,
    query: string,
    options?: { type?: TextSearchType; config?: string },
  ): this;

  /** Array, range or jsonb `column` contains every element of `value` (`@>`). */
  contains(column: ColumnName<Row>, value: PostgrestArrayOperand): this;
  /** Every element of array, range or jsonb `column` is in `value` (`<@`). */
  containedBy(column: ColumnName<Row>, value: PostgrestArrayOperand): this;
  /** Array or range `column` shares at least one element with `value` (`&&`). */
  overlaps(column: ColumnName<Row>, value: PostgrestArrayOperand): this;

  /** Range `column` is entirely after `range`. */
  rangeGt(column: ColumnName<Row>, range: string): this;
  /** Range `column` does not extend before `range`. */
  rangeGte(column: ColumnName<Row>, range: string): this;
  /** Range `column` is entirely before `range`. */
  rangeLt(column: ColumnName<Row>, range: string): this;
  /** Range `column` does not extend after `range`. */
  rangeLte(column: ColumnName<Row>, range: string): this;
  /** Range `column` touches `range` without overlapping it. */
  rangeAdjacent(column: ColumnName<Row>, range: string): this;

  /**
   * Sort by `column`, ascending unless `ascending: false`. Call again for a
   * secondary sort. `referencedTable` sorts the rows of an embedded relation.
   */
  order(column: ColumnName<Row>, options?: OrderOptions): this;
  /** Return at most `count` rows. */
  limit(count: number, options?: ReferencedTableOption): this;
  /**
   * Return rows `from` to `to`, zero-based and both inclusive: `range(0, 9)` is
   * the first 10. The way to paginate.
   */
  range(from: number, to: number, options?: ReferencedTableOption): this;
  /** Cancel the request when `signal` aborts. */
  abortSignal(signal: AbortSignal): this;
  /** Send one more header with this request only, e.g. `x-captcha-response`. */
  setHeader(name: string, value: string): this;

  /** Re-type the rows: for shapes the generated `Database` cannot express. */
  returns<T>(): TypedQuery<Row, Insert, Update, T, RowsUnlessWrite<Data, T[]>>;
  /** `returns<T>()` under supabase-js's newer name. */
  overrideTypes<T>(): TypedQuery<Row, Insert, Update, T, RowsUnlessWrite<Data, T[]>>;
  /** Reject instead of resolving `{ data: null, error }`, for try/catch code. */
  throwOnError(): this;
  /** Refuse the write if it would touch more than `count` rows: a net under a wrong filter. */
  maxAffected(count: number): this;
  /** Run the query, then roll the transaction back: a dry run of a write. */
  rollback(): this;
  /** Resolve the rows as one CSV string instead of objects. */
  csv(): PostgrestTextBuilder;
  /** Resolve the rows as a GeoJSON FeatureCollection, for PostGIS tables. */
  geojson(): PostgrestExplainBuilder;
  /** Resolve the Postgres query plan instead of the rows. Admin callers only. */
  explain(options?: ExplainOptions): PostgrestExplainBuilder;

  /**
   * Walk every matching row instead of stopping at the server's row cap.
   * Throws on error: a `for await` loop has nowhere to put an error value, and
   * ending the iteration quietly looks exactly like reaching the last page.
   * @example for await (const row of client.from('events').select('*').stream()) { ... }
   */
  stream(options?: PaginateOptions): AsyncGenerator<Result, void, undefined>;
  /**
   * `stream()` a page at a time, with the total in `count` when the server
   * reports one. Throws on error.
   */
  paginate(
    options?: PaginateOptions,
  ): AsyncGenerator<{ rows: Result[]; from: number; count: number | null }, void, undefined>;

  /** Resolve one row instead of an array. Fails unless exactly one row matches. */
  single(): TypedSingleQuery<RowsUnlessWrite<Data, Result>>;
  /** Resolve one row, or `null` when none matches. Fails if several match. */
  maybeSingle(): TypedSingleQuery<RowsUnlessWrite<Data, Result | null>>;

  /** The URL path (with query string) this builder targets. Exposed for tests. */
  toPath(): string;
  /** The headers this builder sends (Prefer, Accept). Exposed for tests. */
  toHeaders(): Record<string, string>;
}

/** A builder narrowed to one row by `.single()` / `.maybeSingle()`. */
export interface TypedSingleQuery<Result> extends PromiseLike<PostgrestResponse<Result>> {
  toPath(): string;
  toHeaders(): Record<string, string>;
}

/**
 * What the `client.transaction()` callback is handed.
 *
 * Typed loosely on purpose: the relation names come from the generated
 * `Database` on `client.from()`, and reproducing that overload pair here for a
 * callback that returns nothing buys inference no one reads at the cost of a
 * signature nobody can follow.
 */
export interface TransactionContext {
  from<Row extends object = Record<string, unknown>>(
    table: string,
  ): TypedQuery<Row, Partial<Row>, Partial<Row>>;
}

/**
 * What `client.schema(name)` returns for a schema other than `public`: its
 * functions, called with the profile header PostgREST reads, so
 * `client.schema('pgmq_public').rpc('send', { queue_name, message })` reaches
 * Supabase Queues exactly as it does on Supabase.
 *
 * `from()` is here only to fail with the reason: the REST layer serves tables
 * from `public` alone, and a ported call should say so rather than being
 * "not a function".
 */
export interface SchemaClient<Schema extends GenericSchema = GenericSchema> {
  rpc<Name extends FunctionName<Schema>>(
    fn: Name,
    args?: FunctionArgs<Schema, Name>,
    options?: RpcOptions,
  ): Promise<PostgrestResponse<FunctionReturns<Schema, Name>>>;
  from(table: string): never;
}
